export function getVerifiedPlayerDob(eaId: string | number | undefined | null): string | undefined {
  if (eaId === undefined || eaId === null) return undefined;
  const raw = String(eaId).trim();
  if (!raw) return undefined;
  if (VERIFIED_PLAYER_DOBS_BY_EA_ID[raw]) {
    return VERIFIED_PLAYER_DOBS_BY_EA_ID[raw];
  }
  const num = Number(raw);
  if (Number.isFinite(num) && num > 0xFFFFFF) {
    const baseId = String(num & 0xFFFFFF);
    if (VERIFIED_PLAYER_DOBS_BY_EA_ID[baseId]) {
      return VERIFIED_PLAYER_DOBS_BY_EA_ID[baseId];
    }
  }
  return undefined;
}
